UPDATE lesson
date = #{date}, start_time = #{startTime}, end_time = #{endTime}, fee = #{fee}, status = #{status}, notes = #{notes}, location = #{location}, max_students = #{maxStudents}, actual_students = #{actualStudents}, subject_id = #{subjectId}, grade_id = #{gradeId}, updated_at = NOW()
